//! What actions see and produce: the system variables ([`Sys`]) and the event emitter
//! ([`Emit`]).

use core::marker::PhantomData;

use vertep_core::datamodel::{Environment, EvalError, Event, EventType, SessionInfo, Value};

/// A chart's typed event enum, generated by the macros: one variant per declared event,
/// carrying its payload type.
pub trait ChartEvent: Sized {
    /// The SCXML event name of this variant.
    fn name(&self) -> &'static str;

    /// The payload in its canonical encoding (`undefined` for events without payload).
    fn data(&self) -> Value;

    /// The typed event for an SCXML event, or an error when the name is not a declared event
    /// or the payload does not have the declared type.
    fn from_event(event: &Event) -> Result<Self, EvalError>;

    /// The SCXML event, as an external event.
    fn to_event(&self) -> Event {
        Event {
            data: self.data(),
            ..Event::named(self.name(), EventType::External)
        }
    }
}

/// The SCXML system variables an action can read, through typed accessors.
// @tg: implements:: [[openspec:rust-dsl#Rust Datamodel]]
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Sys {
    pub(crate) event: Event,
    pub(crate) info: SessionInfo,
    pub(crate) env: Environment,
}

impl Sys {
    /// `_event`: the event being processed.
    pub fn event(&self) -> &Event {
        &self.event
    }

    /// `_event.name`.
    pub fn event_name(&self) -> &str {
        &self.event.name
    }

    /// `_sessionid`.
    pub fn session_id(&self) -> &str {
        &self.info.sessionid
    }

    /// `_name`: the chart's name.
    pub fn name(&self) -> Option<&str> {
        self.info.name.as_deref()
    }

    /// `_ioprocessors`.
    pub fn io_processors(&self) -> &Value {
        &self.info.ioprocessors
    }

    /// The input's recorded time in milliseconds since the Unix epoch: the only clock an action
    /// may read, so replaying an input gives the same result.
    pub fn now_ms(&self) -> i64 {
        self.env.now_ms
    }

    /// The input's random seed.
    pub fn seed(&self) -> u64 {
        self.env.seed
    }
}

/// One event an action emitted, before the interpreter turns it into a `<send>`.
#[derive(Clone, Debug, PartialEq)]
pub struct Emitted {
    /// The event name.
    pub name: String,
    /// The payload.
    pub data: Value,
    /// The send target; `#_internal` for a raise.
    pub target: String,
    /// The Event I/O Processor type.
    pub type_: String,
    /// The delay in milliseconds.
    pub delay_ms: u64,
}

impl Emitted {
    /// The emitted event as the value the lowered `<send>` reads through the `_vt_emit`
    /// variable.
    pub fn to_value(&self) -> Value {
        Value::Object(vec![
            ("event".to_string(), Value::String(self.name.clone())),
            ("target".to_string(), Value::String(self.target.clone())),
            ("type".to_string(), Value::String(self.type_.clone())),
            (
                "delay".to_string(),
                Value::String(format!("{}ms", self.delay_ms)),
            ),
            ("data".to_string(), self.data.clone()),
        ])
    }
}

/// How an action sends an event: to whom, through which processor, and when.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct SendOptions {
    /// The target (`#_parent`, `#_scxml_<sessionid>`, `#_<invokeid>`, or a processor-specific
    /// address); `None` sends to this session's external queue.
    pub target: Option<String>,
    /// The Event I/O Processor type; `None` is the SCXML processor.
    pub type_: Option<String>,
    /// The delay in milliseconds.
    pub delay_ms: u64,
}

/// The emitter an action receives: the only way an action has effects besides changing the
/// context. Every emitted event becomes a `<raise>` (internal queue, same macrostep) or a
/// `<send>` (an effect returned by the step), so all effects are journaled. Guards never receive
/// one, and only the datamodel can create one.
// @tg: implements:: [[openspec:rust-dsl#Actions Emit Effects as Events]]
#[derive(Debug)]
pub struct Emit<E> {
    sys: Sys,
    out: Vec<Emitted>,
    _event: PhantomData<fn(E)>,
}

/// The SCXML Event I/O Processor type.
pub const SCXML_PROCESSOR: &str = vertep_core::session::SCXML_EVENT_PROCESSOR;

impl<E> Emit<E> {
    pub(crate) fn new(sys: Sys) -> Self {
        Emit {
            sys,
            out: Vec::new(),
            _event: PhantomData,
        }
    }

    pub(crate) fn into_emitted(self) -> Vec<Emitted> {
        self.out
    }

    /// The system variables.
    pub fn sys(&self) -> &Sys {
        &self.sys
    }

    /// The events emitted so far, in order.
    pub fn emitted(&self) -> &[Emitted] {
        &self.out
    }

    /// Raise an event with any name and payload on the internal queue.
    pub fn raise_untyped(&mut self, name: &str, data: Value) {
        self.out.push(Emitted {
            name: name.to_string(),
            data,
            target: "#_internal".to_string(),
            type_: SCXML_PROCESSOR.to_string(),
            delay_ms: 0,
        });
    }

    /// Send an event with any name and payload.
    pub fn send_untyped(&mut self, name: &str, data: Value, options: SendOptions) {
        let target = options
            .target
            .unwrap_or_else(|| format!("#_scxml_{}", self.sys.session_id()));
        self.out.push(Emitted {
            name: name.to_string(),
            data,
            target,
            type_: options.type_.unwrap_or_else(|| SCXML_PROCESSOR.to_string()),
            delay_ms: options.delay_ms,
        });
    }
}

impl<E: ChartEvent> Emit<E> {
    /// Raise one of the chart's events: it goes on the internal queue and is processed in the
    /// same macrostep.
    pub fn raise(&mut self, event: E) {
        self.raise_untyped(event.name(), event.data());
    }

    /// Send one of the chart's events to this session's external queue.
    pub fn send(&mut self, event: E) {
        self.send_with(event, SendOptions::default());
    }

    /// Send one of the chart's events to a target, such as `#_parent` or another session.
    pub fn send_to(&mut self, target: &str, event: E) {
        self.send_with(
            event,
            SendOptions {
                target: Some(target.to_string()),
                ..SendOptions::default()
            },
        );
    }

    /// Send one of the chart's events with explicit options.
    pub fn send_with(&mut self, event: E, options: SendOptions) {
        self.send_untyped(event.name(), event.data(), options);
    }
}
